#{id}
AND ma.status IN
#{st}
UNION SELECT mp.active_match_user AS user_id, mp.match_id, mp.participation_status AS status FROM match_participant mp WHERE mp.active_match_user IN
#{id} ) x JOIN social_match target ON target.match_id = #{matchId} JOIN social_match sm ON sm.match_id = x.match_id JOIN facility f ON f.facility_id = sm.facility_id JOIN app_user u ON u.user_id = x.user_id WHERE sm.match_id <> target.match_id AND sm.status <> #{cancelledMatchStatus} AND sm.start_at < target.end_at AND sm.end_at > target.start_at ORDER BY sm.start_at, sm.match_id

