  FROM social_match sm
  JOIN match_application ma ON ma.match_id = sm.match_id
                           AND ma.status = #{waitingStatus}
                           AND ma.payment_id IS NOT NULL
 WHERE sm.start_at <= #{now}
   AND sm.status <> #{cancelledMatchStatus}
 ORDER BY sm.match_id

